package edu.dbms.education.auth;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.boot.CommandLineRunner;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Component;

/**
 * Inserts demo users (Faculty, Student, Registrar) on first startup.
 *
 * Why here and not in a Flyway migration?
 *   BCrypt hashes must be generated by the same PasswordEncoder instance
 *   that Spring Security uses for verification. Hard-coding a hash in SQL
 *   works but is fragile (different BCrypt cost/library versions produce
 *   incompatible hashes). Generating them here guarantees consistency.
 *
 * The admin user IS inserted in V7__seed_users.sql because it uses a known,
 * pre-tested hash. The three demo users below are inserted programmatically
 * so the passwords are encoded by the live PasswordEncoder bean.
 *
 * Idempotent: INSERT IGNORE skips rows whose username already exists
 * (UNIQUE constraint on users.username), so restarting the app is safe.
 *
 * Default credentials:
 *   faculty1    / faculty123
 *   student1    / student123
 *   registrar1  / reg123
 */
@Slf4j
@Component
@RequiredArgsConstructor
public class DataInitializer implements CommandLineRunner {

    private final JdbcTemplate    jdbc;
    private final PasswordEncoder passwordEncoder;

    private static final String INSERT_SQL =
            "INSERT IGNORE INTO users (username, password_hash, `role`, is_active, person_id) " +
            "VALUES (?, ?, ?, TRUE, NULL)";

    @Override
    public void run(String... args) {
        insertIfAbsent("faculty1",   "faculty123",  "Faculty");
        insertIfAbsent("student1",   "student123",  "Student");
        insertIfAbsent("registrar1", "reg123",      "Registrar");
    }

    private void insertIfAbsent(String username, String rawPassword, String role) {
        // INSERT IGNORE: no-op if the username already exists
        int rows = jdbc.update(
                INSERT_SQL,
                username,
                passwordEncoder.encode(rawPassword),  // real BCrypt hash
                role
        );
        if (rows > 0) {
            log.info("DataInitializer: inserted demo user '{}' (role={})", username, role);
        }
    }
}
